// Node: "Config"
// The ONLY place you need to edit to change sources, keywords, filters, models or limits.
// The outreach prompt itself lives in the Google Sheet ("Prompts" tab) so it can be
// changed without touching n8n. DEFAULT_PROMPT below is only a fallback.

const config = {
  // Google Sheet that acts as the sales dashboard (the long ID in the sheet URL)
  sheetId: '1-sF_b8OOTMyg7SB3Q2mX9K_6wNkgLwvSr_paK5PCvew',

  // Search terms sent to every job board
  searchTerms: ['executive assistant', 'administrative assistant'],

  // Which boards to query. All three are public APIs with no LinkedIn involvement.
  sources: {
    remotive: true,   // remotive.com/api  (max 4 calls/day, attribution required)
    jobicy: true,     // jobicy.com/api/v2 (max 1 poll/hour, attribution required)
    himalayas: true,  // himalayas.app/jobs/api/search (attribution required)
  },

  // Only consider postings published in the last N days
  maxAgeDays: 21,

  // Safety cap on how many NEW postings go to the LLM per run (cost control)
  maxNewJobsPerRun: 40,

  // Rule based pre-filter (cheap, runs before any LLM call)
  filters: {
    // A title must match at least one of these to be considered relevant
    titleInclude: [
      '\\bexecutive\\s+(assistant|business\\s+partner|support)',
      '\\b(administrative|admin)\\s+(assistant|support|coordinator)',
      '\\bpersonal\\s+assistant\\b',
      '\\bvirtual\\s+(executive\\s+)?assistant\\b',
      '\\bassistant\\s+to\\s+(the\\s+)?(ceo|cfo|coo|cto|founder|co-founder|president|managing\\s+director|executive)',
      '\\bEA\\b',
    ],
    // ...and none of these
    titleExclude: [
      'engineer', 'developer', 'medical', 'dental', 'clinical', 'nurse', 'pharmac',
      'veterinar', 'legal\\s+assistant', 'paralegal', 'teaching', 'research\\s+assistant',
      'lab(oratory)?\\s+assistant', 'sales\\s+(rep|representative)', 'intern\\b',
    ],
    // Hard reject when the TITLE itself says it is not remote
    titleNonRemote: ['hybrid', 'on-?site', 'in[- ]office'],
    // Reject postings that REQUIRE a language other than English
    rejectIfOtherLanguageRequired: true,
    // Reject descriptions that are not written in English
    requireEnglishDescription: true,
  },

  // Claude settings
  llm: {
    validationModel: 'claude-haiku-5-5',  // fast and cheap classifier
    outreachModel: 'claude-sonnet-5-5',   // better writing for the message
    outreachMaxTokens: 700,
    outreachTemperature: 0.7,
  },

  // Values available to the prompt as {{sender_name}}, {{sender_company}}, {{sender_pitch}}
  sender: {
    name: 'Franklin',
    company: 'RAY',
    pitch:
      'RAY places pre-vetted, full-time remote Executive Assistants with founders and executives. ' +
      'Candidates are screened for written English, judgement and tool fluency, and can start within weeks.',
  },

  // Fallback prompt used ONLY if the "Prompts" tab has no row marked Active = TRUE
  defaultPrompt: {
    version: 'fallback-v1',
    system:
      'You write short, warm, specific B2B outreach emails. Never invent facts about the company. ' +
      'No buzzwords, no exclamation marks, no em dashes. Plain text only.',
    user:
      'Write a cold email from {{sender_name}} at {{sender_company}} to the hiring manager at {{company_name}}, ' +
      'who is hiring a "{{job_title}}" ({{location}}).\n\n' +
      'What we offer: {{sender_pitch}}\n\n' +
      'Who the assistant would support: {{executive_supported}}\n' +
      'Key responsibilities from the posting: {{key_responsibilities}}\n' +
      'Tools mentioned: {{tools_mentioned}}\n\n' +
      'Rules: under 120 words, reference two concrete details from the posting, one clear ask ' +
      '(a 15 minute call), format as "Subject: ..." on the first line then a blank line then the body.\n\n' +
      'Job description:\n{{job_description}}',
  },
};

return [{ json: config }];

// Node: "Fetch & Normalize Jobs"  (mode: Run Once for All Items)
// Calls each enabled job board API, maps every posting to one common shape,
// removes duplicates and drops anything already in the Sheet (Jobs or Filtered Out tabs).

const cfg = $('Config').first().json;
const http = this.helpers.httpRequest.bind(this.helpers);
const UA = 'RAY-EA-Outreach/1.0 (n8n workflow; contact via company website)';

// ---------- helpers ----------
function htmlToText(html) {
  if (!html) return '';
  return String(html)
    .replace(/<\s*(script|style)[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, ' ')
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\s*\/\s*(p|div|h[1-6]|ul|ol)\s*>/gi, '\n\n')
    .replace(/<\s*li[^>]*>/gi, '\n- ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;|&apos;|&rsquo;|&lsquo;/g, "'")
    .replace(/&ldquo;|&rdquo;/g, '"')
    .replace(/&mdash;|&ndash;/g, '-')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normUrl(u) {
  if (!u) return '';
  try {
    const url = new URL(String(u).trim());
    ['utm_source', 'utm_medium', 'utm_campaign', 'ref'].forEach((p) => url.searchParams.delete(p));
    return url.toString().replace(/\/$/, '');
  } catch (e) {
    return String(u).trim();
  }
}

function toIso(d) {
  if (d === undefined || d === null || d === '') return '';
  const date = typeof d === 'number' ? new Date(d < 1e12 ? d * 1000 : d) : new Date(d);
  return isNaN(date.getTime()) ? '' : date.toISOString();
}

function joinList(v) {
  if (Array.isArray(v)) return v.filter(Boolean).join(', ');
  return v ? String(v) : '';
}

// ---------- source adapters ----------
const adapters = {
  async remotive(term) {
    const body = await http({
      method: 'GET', url: 'https://remotive.com/api/remote-jobs',
      qs: { search: term, limit: 100 }, headers: { 'User-Agent': UA }, json: true, timeout: 30000,
    });
    return (body.jobs || []).map((j) => ({
      source: 'Remotive',
      sourceJobId: String(j.id),
      url: j.url,
      title: j.title,
      company: j.company_name,
      location: j.candidate_required_location ? `Remote (${j.candidate_required_location})` : 'Remote',
      jobType: j.job_type || '',
      salary: j.salary || '',
      postedAt: toIso(j.publication_date),
      descriptionHtml: j.description,
    }));
  },

  async jobicy(term) {
    const body = await http({
      method: 'GET', url: 'https://jobicy.com/api/v2/remote-jobs',
      qs: { count: 100, tag: term.slice(0, 50) }, headers: { 'User-Agent': UA }, json: true, timeout: 30000,
    });
    return (body.jobs || []).map((j) => ({
      source: 'Jobicy',
      sourceJobId: String(j.id),
      url: j.url,
      title: j.jobTitle,
      company: j.companyName,
      location: j.jobGeo ? `Remote (${j.jobGeo})` : 'Remote',
      jobType: joinList(j.jobType),
      salary: j.salaryMin ? `${j.salaryMin}-${j.salaryMax || ''} ${j.salaryCurrency || ''} ${j.salaryPeriod || ''}`.trim() : '',
      postedAt: toIso(j.pubDate),
      descriptionHtml: j.jobDescription || j.jobExcerpt,
    }));
  },

  async himalayas(term) {
    const body = await http({
      method: 'GET', url: 'https://himalayas.app/jobs/api/search',
      qs: { keyword: term, limit: 20 }, headers: { 'User-Agent': UA }, json: true, timeout: 30000,
    });
    const jobs = body.jobs || body.data || [];
    return jobs.map((j) => {
      const countries = joinList(j.locationRestrictions);
      return {
        source: 'Himalayas',
        sourceJobId: String(j.guid || j.applicationLink || ''),
        url: j.applicationLink || j.guid,
        title: j.title,
        company: j.companyName,
        location: countries ? `Remote (${countries})` : 'Remote (Worldwide)',
        jobType: j.employmentType || '',
        salary: j.minSalary ? `${j.minSalary}-${j.maxSalary || ''} ${j.currency || ''} ${j.salaryPeriod || ''}`.trim() : '',
        postedAt: toIso(j.pubDate),
        descriptionHtml: j.description || j.excerpt,
      };
    });
  },
};

// ---------- fetch ----------
const raw = [];
const errors = [];
for (const [name, enabled] of Object.entries(cfg.sources)) {
  if (!enabled || !adapters[name]) continue;
  for (const term of cfg.searchTerms) {
    try {
      const jobs = await adapters[name](term);
      raw.push(...jobs);
    } catch (e) {
      // One board failing must not stop the others
      errors.push(`${name} "${term}": ${e.message}`);
    }
  }
}

// ---------- normalize, dedupe, skip already processed ----------
const seen = new Set();
for (const nodeName of ['Read Saved Jobs', 'Read Filtered Out']) {
  try {
    for (const row of $(nodeName).all()) {
      const u = normUrl(row.json['Job Posting URL']);
      if (u) seen.add(u);
    }
  } catch (e) { /* tab empty or node not executed */ }
}

const cutoff = Date.now() - cfg.maxAgeDays * 86400000;
const companyTitleKeys = new Set();
const out = [];
const stats = { fetched: raw.length, alreadyInSheet: 0, tooOld: 0, duplicates: 0, kept: 0, errors };

for (const j of raw) {
  const url = normUrl(j.url);
  if (!url || !j.title) continue;
  if (seen.has(url)) { stats.alreadyInSheet++; continue; }
  if (j.postedAt && new Date(j.postedAt).getTime() < cutoff) { stats.tooOld++; continue; }
  // the same job is often cross-posted on several boards
  const ctKey = `${String(j.company).toLowerCase().trim()}|${String(j.title).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()}`;
  if (companyTitleKeys.has(ctKey)) { stats.duplicates++; continue; }
  seen.add(url);
  companyTitleKeys.add(ctKey);

  const descriptionText = htmlToText(j.descriptionHtml);
  out.push({
    source: j.source,
    sourceJobId: j.sourceJobId,
    url,
    title: String(j.title).trim(),
    company: String(j.company || 'Unknown').trim(),
    location: j.location,
    jobType: j.jobType,
    salary: j.salary,
    postedAt: j.postedAt,
    descriptionText,
  });
}

out.sort((a, b) => (b.postedAt || '').localeCompare(a.postedAt || ''));
stats.kept = out.length;

// Stats are attached to every item so the execution log shows what happened
return out.map((job) => ({ json: { ...job, _runStats: stats } }));

// Node: "Rule Pre-Filter"  (mode: Run Once for All Items)
// Cheap deterministic checks BEFORE any LLM call:
//   relevance  -> title must look like an Executive / Admin Assistant role
//   remote     -> boards are remote-only, but reject titles that say hybrid / on-site
//   english    -> description must be written in English and must not REQUIRE another language
// Anything that passes still gets a final LLM check in the next step.

const cfg = $('Config').first().json;
const f = cfg.filters;
const rx = (list) => list.map((p) => new RegExp(p, 'i'));
const includeRx = rx(f.titleInclude);
const excludeRx = rx(f.titleExclude);
const nonRemoteRx = rx(f.titleNonRemote);

const LANGUAGES = [
  'Spanish', 'French', 'German', 'Portuguese', 'Italian', 'Dutch', 'Japanese', 'Mandarin', 'Chinese',
  'Cantonese', 'Korean', 'Arabic', 'Russian', 'Polish', 'Romanian', 'Greek', 'Hebrew', 'Turkish',
  'Swedish', 'Norwegian', 'Danish', 'Finnish', 'Hindi', 'Tagalog', 'Filipino', 'Vietnamese', 'Thai',
  'Indonesian', 'Czech', 'Hungarian', 'Ukrainian', 'Bulgarian', 'Croatian', 'Serbian', 'Slovak',
];
const REQUIRED_WORDS = /(fluen|native|bilingual|proficien|must\s+(speak|be\s+able)|required|mandatory|written\s+and\s+(spoken|verbal)|speak|\bC1\b|\bC2\b)/i;
const OPTIONAL_WORDS = /(nice\s+to\s+have|a\s+plus|is\s+a\s+bonus|preferred|advantage|desirable|beneficial)/i;
const EN_STOPWORDS = new Set(('the and to of a in for with you our is are will on as be this or your we an at by from ' +
  'that have it all team work role who can about their experience support').split(' '));

function englishRatio(text) {
  const words = (text.toLowerCase().match(/[a-zà-ÿ]+/g) || []);
  if (words.length < 40) return 1; // too short to judge, let the LLM decide
  const hits = words.filter((w) => EN_STOPWORDS.has(w)).length;
  return hits / words.length;
}

function languageRequirements(text) {
  const sentences = text.split(/(?<=[.!?\n])\s+/);
  const found = [];
  let otherRequired = false;
  for (const lang of ['English', ...LANGUAGES]) {
    const langRx = new RegExp(`\\b${lang}\\b`, 'i');
    const s = sentences.find((x) => langRx.test(x) && (REQUIRED_WORDS.test(x) || OPTIONAL_WORDS.test(x)));
    if (!s) continue;
    const optional = OPTIONAL_WORDS.test(s);
    found.push(`${lang} (${optional ? 'preferred' : 'required'})`);
    if (lang !== 'English' && !optional) otherRequired = true;
  }
  return { text: found.join('; '), otherRequired };
}

// Second dedupe guard: skip anything already in the Sheet even if the Fetch node
// was pinned (pinned data bypasses the dedupe inside Fetch) or re-run manually.
const normUrl = (u) => String(u || '').trim().replace(/\/$/, '');
const seen = new Set();
for (const nodeName of ['Read Saved Jobs', 'Read Filtered Out']) {
  try {
    for (const row of $(nodeName).all()) {
      const u = normUrl(row.json['Job Posting URL']);
      if (u) seen.add(u);
    }
  } catch (e) { /* tab empty */ }
}

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const job = item.json;
  const key = normUrl(job.url);
  if (!key || seen.has(key)) continue;
  seen.add(key);
  const reasons = [];

  const isRelevant = includeRx.some((r) => r.test(job.title)) && !excludeRx.some((r) => r.test(job.title));
  if (!isRelevant) reasons.push('Title is not an Executive / Admin Assistant role');

  const isRemote = !nonRemoteRx.some((r) => r.test(job.title));
  if (!isRemote) reasons.push('Title says hybrid or on-site');

  const ratio = englishRatio(job.descriptionText);
  const lang = languageRequirements(job.descriptionText);
  const englishText = !f.requireEnglishDescription || ratio >= 0.08;
  const isEnglish = englishText && !(f.rejectIfOtherLanguageRequired && lang.otherRequired);
  if (!englishText) reasons.push('Description is not written in English');
  if (f.rejectIfOtherLanguageRequired && lang.otherRequired) reasons.push(`Requires another language: ${lang.text}`);

  const out = {
    ...job,
    languageRequirements: lang.text || 'None stated',
    rules: { isRelevant, isRemote, isEnglish, englishRatio: Number(ratio.toFixed(3)) },
    rejectStage: reasons.length ? 'Rules' : '',
    rejectReason: reasons.join(' | '),
    passedRules: reasons.length === 0,
  };
  (out.passedRules ? passed : rejected).push(out);
}

// Cost cap: only the newest N relevant jobs go to the LLM this run.
// Overflow is NOT logged anywhere, so it is picked up again on the next run.
const toLlm = passed.slice(0, cfg.maxNewJobsPerRun);

return [...toLlm, ...rejected].map((json) => ({ json }));

// Node: "Build Validation Request"  (mode: Run Once for Each Item)
// Asks Claude to make the final remote / English / relevance decision and to pull out
// personalisation details for the outreach message. Forced tool use guarantees valid JSON.

const cfg = $('Config').first().json;
const job = $json;

const tool = {
  name: 'record_assessment',
  description: 'Record the assessment of one job posting.',
  input_schema: {
    type: 'object',
    properties: {
      is_remote: { type: 'boolean', description: 'True only if the role can be done fully remotely (location restrictions such as "US only" are fine). False if hybrid, on-site or regular office attendance is required.' },
      remote_evidence: { type: 'string', description: 'Short quote or reason for the remote decision.' },
      is_english_speaking: { type: 'boolean', description: 'True if the working language is English and no other language is REQUIRED. A second language listed as a plus is fine.' },
      language_requirements: { type: 'string', description: 'All language requirements stated, e.g. "Fluent English required; Spanish a plus". "None stated" if none.' },
      is_relevant: { type: 'boolean', description: 'True if this is genuinely an Executive Assistant, Administrative Assistant, Personal Assistant or Executive Business Partner role supporting a person or team. False for sales, engineering, medical, legal, teaching, research or recruiting roles.' },
      relevance_evidence: { type: 'string', description: 'Short reason for the relevance decision.' },
      executive_supported: { type: 'string', description: 'Who the assistant would support (e.g. "CEO and co-founder", "VP of Sales"). "Not stated" if unknown.' },
      key_responsibilities: { type: 'array', items: { type: 'string' }, maxItems: 3, description: 'The three most specific responsibilities, paraphrased in under 12 words each.' },
      tools_mentioned: { type: 'array', items: { type: 'string' }, description: 'Software or tools named in the posting.' },
      confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    },
    required: ['is_remote', 'remote_evidence', 'is_english_speaking', 'language_requirements', 'is_relevant',
      'relevance_evidence', 'executive_supported', 'key_responsibilities', 'tools_mentioned', 'confidence'],
  },
};

const requestBody = {
  model: cfg.llm.validationModel,
  max_tokens: 600,
  system: 'You screen job postings for a recruitment team. Judge only from the posting text. Be strict and literal.',
  tools: [tool],
  tool_choice: { type: 'tool', name: 'record_assessment' },
  messages: [{
    role: 'user',
    content:
      `Job title: ${job.title}\nCompany: ${job.company}\nListed location: ${job.location}\n` +
      `Source board: ${job.source} (a remote-only job board)\n\nDescription:\n${String(job.descriptionText).slice(0, 6000)}`,
  }],
};

return { json: { ...job, requestBody } };

// Node: "Parse Validation"  (mode: Run Once for Each Item)
// Merges Claude's verdict back onto the job. Qualified = remote AND English AND relevant.

const job = { ...$('Build Validation Request').item.json };
delete job.requestBody;
const res = $json;

const toolUse = Array.isArray(res.content) ? res.content.find((c) => c.type === 'tool_use') : null;

if (!toolUse) {
  // API error, timeout or unexpected shape: log it so it is visible, retry happens next run
  const msg = (res.error && (res.error.message || JSON.stringify(res.error))) || 'No assessment returned';
  return { json: { ...job, qualified: false, rejectStage: 'LLM error', rejectReason: String(msg).slice(0, 300), retryable: true } };
}

const a = toolUse.input;
const reasons = [];
if (!a.is_remote) reasons.push(`Not remote: ${a.remote_evidence}`);
if (!a.is_english_speaking) reasons.push(`Not English-speaking: ${a.language_requirements}`);
if (!a.is_relevant) reasons.push(`Not relevant: ${a.relevance_evidence}`);

return {
  json: {
    ...job,
    assessment: a,
    languageRequirements: a.language_requirements || job.languageRequirements,
    validationNotes: `Remote: ${a.remote_evidence} | Relevance: ${a.relevance_evidence} | Confidence: ${a.confidence}`,
    qualified: reasons.length === 0,
    rejectStage: reasons.length ? 'LLM validation' : '',
    rejectReason: reasons.join(' | '),
  },
};

// Node: "Build Outreach Request"  (mode: Run Once for Each Item)
// Loads the prompt from the Sheet's "Prompts" tab so tone and wording can be changed
// without editing this workflow. If several rows are Active, each job gets one of them
// at random (simple A/B test); the chosen version is saved next to the message.

const cfg = $('Config').first().json;
const job = $json;
const a = job.assessment || {};

let prompts = [];
try {
  prompts = $('Read Prompt Library').all()
    .map((r) => r.json)
    .filter((r) => String(r['Active']).trim().toUpperCase() === 'TRUE' && r['User Prompt'])
    .map((r) => ({ version: String(r['Version'] || 'unnamed'), system: r['System Prompt'] || '', user: r['User Prompt'] }));
} catch (e) { /* Prompts tab missing: fall back below */ }

const prompt = prompts.length
  ? prompts[Math.floor(Math.random() * prompts.length)]
  : cfg.defaultPrompt;

const vars = {
  job_title: job.title,
  company_name: job.company,
  location: job.location,
  job_description: String(job.descriptionText).slice(0, 5000),
  executive_supported: a.executive_supported || 'Not stated',
  key_responsibilities: (a.key_responsibilities || []).join('; ') || 'Not stated',
  tools_mentioned: (a.tools_mentioned || []).join(', ') || 'None named',
  language_requirements: job.languageRequirements,
  source: job.source,
  sender_name: cfg.sender.name,
  sender_company: cfg.sender.company,
  sender_pitch: cfg.sender.pitch,
};
const fill = (t) => String(t).replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (m, k) => (k in vars ? vars[k] : m));

const requestBody = {
  model: cfg.llm.outreachModel,
  max_tokens: cfg.llm.outreachMaxTokens,
  system: fill(prompt.system),
  messages: [{ role: 'user', content: fill(prompt.user) }],
};

return { json: { ...job, promptVersion: prompt.version, requestBody } };

// Node: "Format Sheet Row"  (mode: Run Once for All Items)
// Turns each job + Claude's message into one row for the "Jobs" tab.
// The first six columns are exactly the ones the brief asks for; the rest help the sales rep.
// If a message failed to generate, the job is skipped (not saved) so it is retried next run.

const MAX_CELL = 4000; // Sheets allows 50k per cell, but long cells make the dashboard unreadable
const rows = [];

$input.all().forEach((item, i) => {
  const job = $('Build Outreach Request').itemMatching(i).json;
  const res = item.json;
  const text = Array.isArray(res.content)
    ? res.content.filter((c) => c.type === 'text').map((c) => c.text).join('\n').trim()
    : '';
  if (!text) return;

  const desc = job.descriptionText.length > MAX_CELL
    ? job.descriptionText.slice(0, MAX_CELL) + '... [truncated, see posting URL]'
    : job.descriptionText;

  rows.push({
    json: {
      'Job Posting URL': job.url,
      'Job Title': job.title,
      'Company Name': job.company,
      'Location': job.location,
      'Job Description': desc,
      'LLM-Generated Outreach Message': text.replace(/\s*—\s*/g, ', '),
      'Status': 'New',
      'Owner': '',
      'Rep Notes': '',
      'Date Posted': job.postedAt ? job.postedAt.slice(0, 10) : '',
      'Date Added': new Date().toISOString().slice(0, 10),
      'Source': job.source,
      'Language Requirements': job.languageRequirements,
      'Validation Notes': job.validationNotes,
      'Prompt Version': job.promptVersion,
    },
  });
});

return rows;

// Node: "Format Rejected Row"  (mode: Run Once for All Items)
// Every posting that fails a check is logged in the "Filtered Out" tab with the reason.
// This keeps the filter auditable and stops the same posting being re-checked every day.
// LLM errors are NOT logged, so those postings are retried on the next run.

return $input.all()
  .map((i) => i.json)
  .filter((j) => !j.retryable)
  .map((j) => ({
    json: {
      'Job Posting URL': j.url,
      'Job Title': j.title,
      'Company Name': j.company,
      'Location': j.location,
      'Source': j.source,
      'Rejected At': j.rejectStage,
      'Reason': j.rejectReason,
      'Language Requirements': j.languageRequirements,
      'Date Checked': new Date().toISOString().slice(0, 10),
    },
  }));
